Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='deviceerasure', at=datetime(2026, 11, 2, 0, 0, 0), actor='assistant', title='An erasure leaves no key, opened word or wholly erased print on the device', body="After an erasure, no key it names is held in IndexedDB, in the core or in any message between the worker and the page. No word such a key opened stays in the core's memo, in the blocks store or in the page. A line whose every slot is erased loses its print from the content store and from the core, and is read from its husk from then on. A print that seals an erased slot and a live one is kept until every slot of its line is erased. The browser's HTTP cache, which no page can reach, is outside this rule.", rationale="The owner chose that an erasure removes what the device's own code holds, in the same transaction as the keys, and accepted one more download of the skeleton for the husks.", supersedes=()))